#' Worst-Case Bounds
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param control .
#' @param armTreat .
#' @param mode .
#' @param ymin .
#' @param ymax .
#' @param level .
#' @param nboot .
#' @param seed .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$ref} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$res} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$means} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bndPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$ref$asDF}
#'
#' \code{as.data.frame(results$ref)}
#'
#' @export
exbounds <- function(
    data,
    outcome,
    treat,
    control = "",
    armTreat = "",
    mode = "random",
    ymin = "",
    ymax = "",
    level = 95,
    nboot = 1000,
    seed = 1234,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("exbounds requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL))


    options <- exboundsOptions$new(
        outcome = outcome,
        treat = treat,
        control = control,
        armTreat = armTreat,
        mode = mode,
        ymin = ymin,
        ymax = ymax,
        level = level,
        nboot = nboot,
        seed = seed,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- exboundsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

